1	import { createServerClient } from "@supabase/ssr";
2	import { cookies } from "next/headers";
3	
4	// Not parameterized with <Database> yet — src/lib/types/database.ts is still
5	// a placeholder. Wire it back in once it's regenerated from the real schema
6	// (see the comment in that file).
7	export async function createClient() {
8	  const cookieStore = await cookies();
9	
10	  return createServerClient(
11	    process.env.NEXT_PUBLIC_SUPABASE_URL!,
12	    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
13	    {
14	      cookies: {
15	        getAll() {
16	          return cookieStore.getAll();
17	        },
18	        setAll(cookiesToSet) {
19	          try {
20	            cookiesToSet.forEach(({ name, value, options }) =>
21	              cookieStore.set(name, value, options),
22	            );
23	          } catch {
24	            // setAll called from a Server Component — safe to ignore
25	            // because middleware refreshes the session on every request.
26	          }
27	        },
28	      },
29	    },
30	  );
31	}
